-- Real Estate Analytics: sample data (20 agents + 180 customers = 200 people, 250 properties)
-- Compatible with MySQL 8 / PostgreSQL / SQLite (standard SQL)

DROP TABLE IF EXISTS properties;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS agents;

CREATE TABLE agents (
    agent_id        INT PRIMARY KEY,
    first_name      VARCHAR(50)  NOT NULL,
    last_name       VARCHAR(50)  NOT NULL,
    gender          CHAR(1),
    email           VARCHAR(100) UNIQUE NOT NULL,
    phone           VARCHAR(15),
    city            VARCHAR(50),
    hire_date       DATE,
    experience_yrs  INT,
    commission_pct  DECIMAL(4,2),
    status          VARCHAR(10)
);

CREATE TABLE customers (
    customer_id     INT PRIMARY KEY,
    first_name      VARCHAR(50)  NOT NULL,
    last_name       VARCHAR(50)  NOT NULL,
    gender          CHAR(1),
    age             INT,
    email           VARCHAR(100) UNIQUE NOT NULL,
    phone           VARCHAR(15),
    city            VARCHAR(50),
    customer_type   VARCHAR(10),      -- Buyer / Seller / Renter / Investor
    budget_inr      BIGINT,
    registration_date DATE,
    lead_source     VARCHAR(30)
);

CREATE TABLE properties (
    property_id     INT PRIMARY KEY,
    agent_id        INT NOT NULL,
    customer_id     INT,              -- buyer/renter; NULL if still available
    property_type   VARCHAR(20),
    listing_type    VARCHAR(10),      -- Sale / Rent
    city            VARCHAR(50),
    locality        VARCHAR(60),
    bedrooms        INT,
    bathrooms       INT,
    area_sqft       INT,
    year_built      INT,
    furnishing      VARCHAR(20),
    listing_price_inr BIGINT,
    final_price_inr BIGINT,           -- NULL if not sold/rented
    listing_date    DATE,
    closing_date    DATE,
    status          VARCHAR(15),      -- Available / Sold / Rented / Under Offer
    FOREIGN KEY (agent_id) REFERENCES agents(agent_id),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);





-- Sample analytics queries
-- 1) Revenue and sales count by agent
SELECT a.agent_id, a.first_name, a.last_name,
       COUNT(*) AS deals, SUM(p.final_price_inr) AS total_value
FROM agents a JOIN properties p ON p.agent_id = a.agent_id
WHERE p.status = 'Sold'
GROUP BY a.agent_id, a.first_name, a.last_name
ORDER BY total_value DESC;

-- 2) Average price per sq ft by city and property type (sales)
SELECT city, property_type, ROUND(AVG(final_price_inr * 1.0 / area_sqft)) AS avg_price_per_sqft
FROM properties
WHERE status = 'Sold' AND listing_type = 'Sale'
GROUP BY city, property_type;

-- 3) Customer type breakdown with average budget
SELECT customer_type, COUNT(*) AS customers, ROUND(AVG(budget_inr)) AS avg_budget
FROM customers GROUP BY customer_type;
